// Generates src/emit/fuel.gen.ts: the fuel pool hovers draw a fresh literal
// type node from before every chunk (docs/EMIT.md "The run protocol").
//   node scripts/gen-fuel.ts [chunks]
import { writeFileSync } from "node:fs";
import { encNat } from "../src/types/codec-heap.ts";

const n = Number(process.argv[2] ?? 20000);
const lines = [
  "// Generated by scripts/gen-fuel.ts. Do not edit.",
  "/** One literal type node per chunk, keyed by the chunk number (an int). */",
  "export interface Pool {",
];
for (let k = 0; k < n; k++) lines.push(`  "${encNat(k)}": 0;`);
lines.push("}");
writeFileSync(new URL("../src/emit/fuel.gen.ts", import.meta.url), lines.join("\n") + "\n");
